const ICONS={calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',book:'<path d="M12 6c-3-3-7-3-10-2v15c4-1 7-1 10 2m0-15c3-3 7-3 10-2v15c-4-1-7-1-10 2V6Z"/>',bag:'<path d="M5 7h14l2 14H3L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',sprout:'<path d="M12 22V12M12 15C4 16 2 10 3 5c6-1 10 3 9 10Zm0-3C11 5 16 2 22 3c0 6-3 10-10 9Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',sliders:'<path d="M4 3v5m0 4v9M12 3v10m0 4v4M20 3v2m0 4v12M1 8h6m2 9h6m2-12h6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M16 4a3 3 0 0 1 0 6m2 5c2 1 3 3 3 6"/>',check:'<path d="m5 12 4 4L19 6"/>',refresh:'<path d="M20 8a9 9 0 1 0 1 7M20 3v6h-6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 0 10 8 16 8-6 12-12 8-16Z"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',leaf:'<path d="M20 3C4 1 1 12 6 17c6 6 16-1 14-14ZM4 21 16 9"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.leaf}</svg>`;
const ingredients={moong:{name:'Split moong dal',unit:'g',category:'PANTRY STAPLES'},rice:{name:'Brown rice',unit:'g',category:'PANTRY STAPLES'},carrot:{name:'Carrot',unit:'',category:'FRESH PRODUCE'},spinach:{name:'Spinach',unit:'g',category:'FRESH PRODUCE'},cumin:{name:'Cumin seeds',unit:'tsp',category:'PANTRY STAPLES'},turmeric:{name:'Turmeric',unit:'tsp',category:'PANTRY STAPLES'},lemon:{name:'Lemon',unit:'',category:'FRESH PRODUCE'},chickpea:{name:'Sprouted chickpeas',unit:'g',category:'PANTRY STAPLES'},cucumber:{name:'Cucumber',unit:'',category:'FRESH PRODUCE'},tomato:{name:'Tomato',unit:'',category:'FRESH PRODUCE'},coriander:{name:'Fresh coriander',unit:'g',category:'FRESH PRODUCE'},basil:{name:'Fresh basil',unit:'g',category:'FRESH PRODUCE'},pepper:{name:'Black pepper',unit:'tsp',category:'PANTRY STAPLES'},millet:{name:'Foxtail millet',unit:'g',category:'PANTRY STAPLES'},peas:{name:'Green peas',unit:'g',category:'FRESH PRODUCE'},ginger:{name:'Fresh ginger',unit:'g',category:'FRESH PRODUCE'},coconut:{name:'Coconut milk',unit:'ml',category:'PANTRY STAPLES'},beans:{name:'Green beans',unit:'g',category:'FRESH PRODUCE'},cashew:{name:'Cashews',unit:'g',category:'PANTRY STAPLES'},noodles:{name:'Whole wheat noodles',unit:'g',category:'PANTRY STAPLES'},sesame:{name:'Sesame seeds',unit:'tsp',category:'PANTRY STAPLES'},"pumpkin": {"name": "Pumpkin", "unit": "g", "category": "FRESH PRODUCE"}, "freshcoconut": {"name": "Fresh coconut flesh", "unit": "g", "category": "FRESH PRODUCE"}, "mint": {"name": "Fresh mint", "unit": "g", "category": "FRESH PRODUCE"}, "beetroot": {"name": "Beetroot", "unit": "", "category": "FRESH PRODUCE"}, "corn": {"name": "Fresh sweetcorn kernels", "unit": "g", "category": "FRESH PRODUCE"}, "lauki": {"name": "Bottle gourd (lauki)", "unit": "g", "category": "FRESH PRODUCE"}, "curryleaves": {"name": "Fresh curry leaves", "unit": "sprigs", "category": "FRESH PRODUCE"}, "bellpepper": {"name": "Bell pepper", "unit": "", "category": "FRESH PRODUCE"}};
const recipes=[
 {id:'khichdi',name:'Golden moong khichdi',desc:'Comfort in a bowl, with colourful vegetables.',image:'khichdi',time:30,category:'Comfort bowls',nuts:false,prep:'Rinse the rice and dal well. Soak brown rice for 4 hours, or follow your packet instructions.',ingredients:{moong:100,rice:100,carrot:1,spinach:60,cumin:1,turmeric:.5,lemon:.5},steps:['Rinse the soaked brown rice and moong dal. Chop the carrot and spinach.','Add rice, dal, carrot, cumin and turmeric to a pressure cooker with 700 ml water per 2 servings.','Cook according to your cooker and rice instructions until the rice and dal are tender. Release pressure safely.','Stir in spinach and simmer until cooked. Add water for a softer texture, season to taste, and finish with lemon.']},
 {id:'chickpea',name:'Rainbow chickpea bowl',desc:'Fresh, crunchy, and full of everyday goodness.',image:'chickpea',time:15,category:'Quick & fresh',nuts:false,prep:'Use fully cooked chickpeas. If starting from dried, soak and cook them ahead of time.',ingredients:{chickpea:250,cucumber:1,tomato:2,carrot:1,lemon:1,coriander:15,cumin:.5},steps:['Drain the cooked chickpeas. Rinse and chop the cucumber, tomatoes, carrot and coriander.','Combine the vegetables and chickpeas in a large bowl.','Add freshly squeezed lemon and cumin. Season to taste and toss gently.','Divide between bowls and enjoy fresh.']},
 {id:'soup',name:'Tomato & basil soup',desc:'A warm, simple pause in your busy day.',image:'soup',time:25,category:'Comfort bowls',nuts:false,prep:'Keep a little fresh basil aside for serving.',ingredients:{tomato:6,carrot:1,basil:15,pepper:.5,ginger:10},steps:['Wash and roughly chop the tomatoes, carrot and ginger.','Add to a pot with 350 ml water per 2 servings. Cover and simmer until the vegetables are soft.','Allow to cool slightly. Blend carefully with the basil until smooth.','Return to the pot, adjust the consistency with water, and warm through. Season with pepper and serve.']},
 {id:'millet',name:'Garden millet bowl',desc:'Fluffy millet meets your favourite vegetables.',image:'bowl',time:30,category:'Comfort bowls',nuts:true,prep:'Rinse the millet well. Soak if recommended on your packet. This recipe contains cashews.',ingredients:{millet:140,carrot:1,peas:100,ginger:10,cumin:1,cashew:20,lemon:.5},steps:['Rinse the millet and cook it with water according to the packet instructions.','In a separate pan, gently simmer chopped carrot, peas and ginger in a splash of water until tender.','Add cumin and cooked millet. Stir gently and warm through.','Top with cashews and lemon juice. Season to taste.']},
 {id:'stew',name:'Coconut vegetable stew',desc:'Creamy coconut, tender greens, gentle flavours.',image:'curry',time:25,category:'Comfort bowls',nuts:false,prep:'Chop vegetables to a similar size so they cook evenly. Check coconut milk ingredients for your preferences.',ingredients:{carrot:2,beans:150,peas:100,ginger:10,coconut:250,pepper:.5},steps:['Chop the carrots, beans and ginger.','Add the chopped vegetables and peas to a pot with 200 ml water per 2 servings. Simmer until tender.','Stir in the coconut milk and gently warm without boiling rapidly.','Season to taste with black pepper. Serve warm.']},
 {id:'noodles',name:'Sesame veggie noodles',desc:'A colourful tangle of noodles and fresh greens.',image:'noodles',time:20,category:'Quick & fresh',nuts:false,prep:'This recipe contains wheat and sesame. Use noodles suited to your household’s needs.',ingredients:{noodles:150,carrot:1,beans:100,spinach:60,sesame:2,lemon:1,ginger:10},steps:['Cook the noodles according to the packet instructions, then drain.','Slice the carrot and beans finely. Simmer with ginger and a splash of water until tender.','Add spinach and cooked noodles, and toss gently until the spinach is cooked.','Finish with sesame seeds and lemon juice. Season to taste and serve.']},
 {"id":"pumpkin-soup","name":"Pumpkin & ginger soup","desc":"Velvety pumpkin, gentle ginger, and a little coconut creaminess.","image":"pumpkin-soup","time":25,"category":"Comfort bowls","nuts":false,"prep":"Peel and deseed the pumpkin. Use freshly made coconut milk; the active time excludes making it.","ingredients":{"pumpkin":500,"ginger":10,"coconut":100,"cumin":0.5,"coriander":10},"steps":["Cut the pumpkin into small, even cubes and finely slice the ginger.","Put the pumpkin, ginger and cumin in a pot with 350 ml water per 2 servings. Cover and simmer gently until the pumpkin is tender.","Let it cool a little. Blend until smooth, adding water if you prefer a thinner soup.","Warm gently, then switch off the heat. Stir in the coconut milk, season to taste, and finish with fresh coriander."]},
 {"id":"carrot-soup","name":"Carrot & cumin soup","desc":"A sunny bowl of carrots with the warmth of cumin.","image":"carrot-soup","time":20,"category":"Comfort bowls","nuts":false,"prep":"Slice carrots thinly so they soften quickly. Use fresh homemade coconut milk.","ingredients":{"carrot":4,"cumin":1,"ginger":10,"coconut":150,"coriander":10},"steps":["Wash and thinly slice the carrots. Finely chop the ginger.","Combine the carrots, ginger and cumin in a pot with 350 ml water per 2 servings. Cover and simmer until just tender.","Allow to cool slightly before blending. Return to the pot and gently warm, adjusting the consistency with water.","Turn off the heat, stir in the coconut milk, season to taste, and add chopped coriander."]},
 {"id":"spinach-corn","name":"Spinach & sweetcorn soup","desc":"Sweet corn and fresh greens in a softly creamy bowl.","image":"spinach-corn","time":20,"category":"Comfort bowls","nuts":false,"prep":"Use fresh sweetcorn kernels and wash the spinach thoroughly. Prepare coconut milk ahead of time.","ingredients":{"spinach":120,"corn":200,"ginger":10,"coconut":150,"pepper":0.5},"steps":["Rinse the corn and spinach. Finely chop the ginger and roughly chop the spinach.","Simmer the corn and ginger in 350 ml water per 2 servings until the corn is tender. Keep a spoonful of corn aside for texture.","Let the remaining corn mixture cool a little, blend, and return to the pot. Add the spinach and reserved corn; simmer briefly until the spinach is cooked.","Switch off the heat. Stir in the coconut milk and black pepper, season to taste, and serve warm."]},
 {"id":"cucumber-salad","name":"Cucumber & coconut salad","desc":"Cool cucumber, fresh coconut, and a bright mint finish.","image":"cucumber-salad","time":10,"category":"Quick & fresh","nuts":false,"prep":"Grate fresh coconut and wash the mint. This recipe contains coconut and sesame.","ingredients":{"cucumber":2,"freshcoconut":60,"mint":10,"lemon":0.5,"sesame":1},"steps":["Wash the cucumbers and cut them into thin half-moons or small cubes.","Grate the fresh coconut and finely chop the mint leaves.","Combine the cucumber, coconut and mint in a bowl. Squeeze over the lemon and season to taste.","Toss gently, sprinkle with sesame seeds, and serve immediately while crisp."]},
 {"id":"beetroot-salad","name":"Beetroot & carrot salad","desc":"A colourful crunch with lemon, coriander, and sesame.","image":"beetroot-salad","time":15,"category":"Quick & fresh","nuts":false,"prep":"Scrub and peel the beetroot and carrots. This recipe contains sesame.","ingredients":{"beetroot":2,"carrot":2,"cucumber":1,"lemon":1,"coriander":10,"sesame":2},"steps":["Wash, peel and coarsely grate the beetroot and carrots. Cut the cucumber into small pieces.","Finely chop the coriander and combine it with the vegetables in a large bowl.","Add freshly squeezed lemon juice and season to taste. Toss until evenly mixed.","Sprinkle with sesame seeds, divide between bowls, and enjoy fresh."]},
 {"id":"millet-upma","name":"Vegetable millet upma","desc":"Fluffy millet with plenty of vegetables and fresh curry leaves.","image":"millet-upma","time":25,"category":"Comfort bowls","nuts":true,"prep":"Rinse the millet and soak if recommended on the packet. Contains cashews: soak them for 6–8 hours in the refrigerator, then drain and rinse. Active time excludes soaking.","ingredients":{"millet":120,"carrot":1,"beans":100,"peas":100,"curryleaves":2,"cumin":1,"ginger":10,"freshcoconut":30,"lemon":0.5,"cashew":20},"steps":["Rinse the millet. Cut the carrot and green beans into small, even pieces, and chop the ginger.","Cook the millet in water according to the packet instructions, with cumin, ginger and torn curry leaves.","Steam the carrot, beans and peas separately until just tender, then gently fold them into the cooked millet.","Turn off the heat. Add freshly grated coconut and chopped soaked cashews, squeeze over the lemon, season to taste, and fluff with a fork."]},
 {"id":"lauki-khichdi","name":"Lauki & moong khichdi","desc":"A soft one-pot meal with bottle gourd and gentle spices.","image":"lauki-khichdi","time":30,"category":"Comfort bowls","nuts":false,"prep":"Soak brown rice for 4 hours or as directed on the packet; rinse the dal. Use fresh, non-bitter bottle gourd and discard it if bitter. Active time excludes soaking.","ingredients":{"lauki":400,"moong":60,"rice":60,"carrot":1,"cumin":1,"turmeric":0.5,"coriander":10,"lemon":0.5},"steps":["Peel and dice the bottle gourd, removing mature seeds. Dice the carrot and rinse the soaked rice and dal.","Add the rice, dal, bottle gourd, carrot, cumin and turmeric to a pressure cooker with 700 ml water per 2 servings.","Cook according to your cooker and brown rice instructions until the grains and dal are tender. Let the pressure release safely.","Stir gently and add water if needed for a soft texture. Turn off the heat, season to taste, and finish with coriander and lemon juice."]},
 {"id":"cashew-curry","name":"Creamy cashew vegetable curry","desc":"Tender vegetables in a mellow, dairy-free cashew sauce.","image":"cashew-curry","time":30,"category":"Comfort bowls","nuts":true,"prep":"Contains cashews. Soak them for 6–8 hours in the refrigerator, then drain and rinse. Prepare fresh coconut milk. Active time excludes soaking.","ingredients":{"cashew":50,"carrot":1,"beans":150,"peas":100,"bellpepper":1,"ginger":10,"cumin":1,"turmeric":0.5,"coconut":100,"coriander":10},"steps":["Chop the carrot, green beans and bell pepper into even pieces. Blend the drained, soaked cashews with a little fresh water until smooth.","Simmer the carrot, beans, peas, ginger, cumin and turmeric in 200 ml water per 2 servings until nearly tender.","Add the bell pepper and cashew paste. Cook gently for a few minutes, stirring and adding water as needed, until the vegetables are tender and the sauce is warm.","Switch off the heat. Stir in the coconut milk, season to taste, and finish with fresh coriander."]}
];
// The satvic layer: season, time of day, raw or cooked, and what to soak the night before.
// Seasons follow the six Indian ritus, mapped to months (approximate, as most almanacs do).
const RITU=[{id:'shishir',name:'Shishir',en:'late winter',months:[0,1],line:'Cold mornings, slow evenings. Warm one-pot meals and the last winter roots.'},{id:'vasant',name:'Vasant',en:'spring',months:[2,3],line:'The season turns light. More raw plates, more greens, less heaviness.'},{id:'grishma',name:'Grishma',en:'summer',months:[4,5],line:'The heat is up. Cooling, water-rich food, and nothing heavy after dark.'},{id:'varsha',name:'Varsha',en:'monsoon',months:[6,7],line:'Monsoon weeks. Cooked, warm and simple, with gentle spice.'},{id:'sharad',name:'Sharad',en:'early autumn',months:[8,9],line:'Clear days after the rains. Light grains and the first gourds.'},{id:'hemant',name:'Hemant',en:'early winter',months:[10,11],line:'Early winter. Warm, grounding bowls and the season’s roots.'}];
const ALL_YEAR=['shishir','vasant','grishma','varsha','sharad','hemant'];
const MOMENT={midday:{short:'MIDDAY',tag:'Midday',label:'Best at midday'},sunset:{short:'BEFORE SUNSET',tag:'Before sunset',label:'Light enough for an early dinner'}};
const SATVIC={
 khichdi:{moment:'sunset',raw:false,ritu:ALL_YEAR,soak:{hours:4,what:'brown rice',key:'rice'},why:'Rice and moong in one pot, with no onion or garlic. In satvic kitchens khichdi is the everyday meal: simple, warm and cooked fresh.'},
 chickpea:{name:'Sprouted chickpea bowl',desc:'Raw, crunchy, and sprouted in your own kitchen.',prep:'Soak dried chickpeas for 8 hours, drain, then leave them covered for about a day until small tails appear. Steam them for a few minutes if you prefer them softer.',moment:'midday',raw:true,ritu:['vasant','grishma','sharad'],soak:{hours:8,what:'dried chickpeas',grams:100,note:'then sprout for a day'},why:'Sprouting turns a pantry staple into fresh food. Eaten raw at midday, when satvic tradition says appetite is strongest.'},
 soup:{moment:'sunset',raw:false,ritu:['hemant','shishir','varsha'],why:'Whole tomatoes, ginger and basil, simmered in water with no oil. Light enough for an early dinner.'},
 millet:{moment:'midday',raw:false,ritu:['vasant','sharad','hemant'],soak:{hours:6,what:'foxtail millet',key:'millet'},why:'Millet is an old Indian grain that cooks quickly once soaked. The vegetables are simmered, never fried.'},
 stew:{moment:'sunset',raw:false,ritu:['varsha','hemant','shishir'],why:'Vegetables simmered in water, with coconut milk stirred in gently at the end. Mild spice, no onion or garlic.'},
 noodles:{moment:'midday',raw:false,ritu:['vasant','grishma','sharad'],why:'The most modern plate here: whole-grain noodles with plenty of greens, kept simple with sesame and lemon. Contains wheat.'},
 'pumpkin-soup':{moment:'sunset',raw:false,ritu:['sharad','hemant','shishir'],why:'A seasonal gourd, simmered and blended, with coconut stirred in off the heat. Made for the cooling months.'},
 'carrot-soup':{moment:'sunset',raw:false,ritu:['hemant','shishir'],why:'Winter carrots and cumin, with no oil. A warm, light early dinner.'},
 'spinach-corn':{moment:'sunset',raw:false,ritu:['varsha','hemant'],why:'Fresh greens and sweetcorn, cooked briefly to keep them bright. Coconut goes in off the heat.'},
 'cucumber-salad':{moment:'midday',raw:true,ritu:['vasant','grishma'],why:'Raw, cooling and water-rich: the plate satvic kitchens reach for in the heat of the day.'},
 'beetroot-salad':{moment:'midday',raw:true,ritu:['hemant','shishir','vasant'],why:'Raw winter roots, grated fresh and dressed with lemon. Best eaten as soon as it is made.'},
 'millet-upma':{moment:'midday',raw:false,ritu:['varsha','sharad','hemant','shishir'],soak:{hours:6,what:'cashews',key:'cashew',note:'in the fridge'},why:'Millet in place of semolina, with steamed vegetables and fresh coconut. Soaking the cashews the night before is part of the recipe.'},
 'lauki-khichdi':{moment:'sunset',raw:false,ritu:['grishma','varsha','sharad'],soak:{hours:4,what:'brown rice',key:'rice'},why:'Bottle gourd is a classic warm-weather vegetable in satvic cooking: mild, watery and quick to cook with dal.'},
 'cashew-curry':{moment:'midday',raw:false,ritu:['hemant','shishir'],soak:{hours:6,what:'cashews',key:'cashew',note:'in the fridge'},why:'Soaked cashews make the sauce creamy without dairy or frying. A richer meal, so it belongs at midday.'}
};
recipes.forEach(r=>Object.assign(r,SATVIC[r.id]));
find_('chickpea').steps[0]='Rinse the sprouted chickpeas. Chop the cucumber, tomatoes, carrot and coriander.';
function find_(id){return recipes.find(r=>r.id===id);}
function ritu(d=new Date()){return RITU.find(s=>s.months.includes(d.getMonth()));}
function isoWeek(d=new Date()){const t=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));const day=t.getUTCDay()||7;t.setUTCDate(t.getUTCDate()+4-day);const y=new Date(Date.UTC(t.getUTCFullYear(),0,1));return Math.ceil(((t-y)/864e5+1)/7);}
function daysToHarvest(){const d=new Date().getDay();return (8-d)%7||7;}
const inSeason=r=>r.ritu.includes(ritu().id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<17?'Good afternoon':'Good evening';}
const KEY='satvic-kitchen-concept-v1';
const fresh=()=>({servings:2,time:30,nutFree:false,plan:['khichdi','chickpea','soup'],pantry:[],bought:[],cooked:[],planDone:[],feedback:{},view:'plan',name:'',appetite:'',onboarded:false,soaked:[]});
let state=fresh();try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&typeof saved==='object'){state={...state,...saved};if(saved.onboarded===undefined)state.onboarded=true;state.servings=Math.max(1,Math.min(8,Number(state.servings)||2));state.time=[20,30,45].includes(state.time)?state.time:30;state.plan=Array.from({length:3},(_,i)=>recipes.some(r=>r.id===state.plan?.[i])?state.plan[i]:null);for(const key of ['pantry','bought','cooked','planDone','soaked'])if(!Array.isArray(state[key]))state[key]=[];state.name=String(state.name||'').slice(0,40);if(!state.feedback||typeof state.feedback!=='object')state.feedback={};}}catch{}
const VIEWS=['plan','recipes','shopping','progress'],hashView=location.hash.slice(1);
let view=VIEWS.includes(hashView)?hashView:VIEWS.includes(state.view)?state.view:'plan',filter='All recipes',query='',shoppingTab='need',swapIndex=0,toastTimer;
const find=id=>recipes.find(r=>r.id===id);
const format=n=>Number.isInteger(n)?String(n):String(Math.round(n*10)/10);
// Quantities read the way a cook says them: ½ tsp, 1½ lemons, 3 medium carrots, whole grams.
const FRAC=[[0,''],[.25,'¼'],[.5,'½'],[.75,'¾'],[1,'']];
function nice(n){const w=Math.floor(n+1e-9),f=n-w;let best=FRAC[0],d=1;for(const p of FRAC){const dd=Math.abs(f-p[0]);if(dd<d){d=dd;best=p;}}if(d>.04)return format(n);const whole=best[0]===1?w+1:w;return best[1]?(whole?whole+best[1]:best[1]):String(whole);}
const SIZE={carrot:'medium',tomato:'medium',beetroot:'medium',cucumber:'medium'};
const quantity=(key,n)=>{const u=ingredients[key].unit;if(!u)return `${nice(n)}${SIZE[key]?' '+SIZE[key]:''}`;if(u==='g'||u==='ml')return `${Math.max(1,Math.round(n))} ${u}`;if(u==='sprigs')return `${nice(n)} ${n>1?'sprigs':'sprig'}`;return `${nice(n)} ${u}`;};
// Whole produce can't be bought in halves: say how many to pick up.
const buyNote=(key,n)=>!ingredients[key].unit&&Math.abs(n-Math.round(n))>.01?`buy ${Math.ceil(n)}`:'';
// Shared by the recipe dialog and Sprout so every quantity is scaled the same way (recipes are written for 2).
const people=n=>`${n} ${n===1?'person':'people'}`;
function scaledIngredients(r){return Object.entries(r.ingredients).map(([key,n])=>({key,name:ingredients[key].name,amount:quantity(key,n*state.servings/2)}));}
function scaledStep(step){return step.replace(/(\d+) ml/g,(_,ml)=>`${format(ml*state.servings/2)} ml`).replaceAll('per 2 servings',`for ${people(state.servings)}`);}
function save(){state.view=view;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
function aggregate(){const totals={};state.plan.filter(Boolean).forEach(id=>{for(const [key,n]of Object.entries(find(id).ingredients))totals[key]=(totals[key]||0)+n*state.servings/2;});return totals;}
function available(){return recipes.filter(r=>r.time<=state.time&&(!state.nutFree||!r.nuts));}
function meta(r){return `<div class="meal-meta"><span>${icon('clock')}${r.time} min</span><span>${icon('people')}${state.servings} ${state.servings===1?'person':'people'}</span></div>`;}
function pageHeading(kicker,title,desc){return `<div class="page-heading"><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div>`;}
function steps(){return `<div class="steps-bar" aria-label="How it works"><button class="step-link ${view==='plan'?'current':''}" data-view="plan"><span>1</span>Plan</button><div class="step-line"></div><button class="step-link ${view==='shopping'?'current':''}" data-view="shopping"><span>2</span>Shop</button><div class="step-line"></div><button class="step-link ${view==='progress'?'current':''}" data-view="progress"><span>3</span>Cook</button></div>`;}
function satvicTags(r){return `<div class="satvic-tags"><span>${r.raw?'Raw':'Cooked fresh'}</span>${r.soak?`<span>Soak ${r.soak.hours} h</span>`:''}<span>${MOMENT[r.moment].tag}</span></div>`;}
function cardHTML(r){const added=state.plan.includes(r.id);return `<article class="recipe-card"><button class="recipe-image" data-recipe="${r.id}" aria-label="View ${r.name}"><img src="assets/${r.image}.jpg" alt="" loading="lazy"><span class="image-tag">${inSeason(r)?'In season':r.category}</span></button><div class="recipe-body"><h3>${r.name}</h3><p>${r.desc}</p>${satvicTags(r)}<div class="recipe-card-foot">${meta(r)}<button class="add-button ${added?'added':''}" data-add="${r.id}" aria-label="${added?'Choose a day for':'Add to plan:'} ${r.name}">${added?icon('check'):'+'}</button></div></div></article>`;}
const FILTERS=['All recipes','In season','Raw','Soak ahead','Quick & fresh','Comfort bowls'];
function matchesFilter(r){return filter==='All recipes'?true:filter==='In season'?inSeason(r):filter==='Raw'?r.raw:filter==='Soak ahead'?!!r.soak:r.category===filter;}
function recipeCards(){const q=query.toLowerCase();const matching=available().filter(r=>matchesFilter(r)&&(r.name+' '+r.desc+' '+Object.keys(r.ingredients).map(k=>ingredients[k].name).join(' ')).toLowerCase().includes(q));return matching.length?matching.map(cardHTML).join(''):`<div class="empty-state" style="grid-column:1/-1">${icon('search')}<h3>Nothing matches that.</h3><p>Try another ingredient, or loosen your time and nut preferences.</p><button class="button outline" data-action="clear-filter">Clear search & filters</button></div>`;}
// This week's harvest: six in-season recipes that fit your preferences, rotating every Monday.
function harvest(){const s=available().filter(inSeason);if(s.length<=6)return s;const start=(isoWeek()*5)%s.length;return Array.from({length:6},(_,i)=>s[(start+i)%s.length]);}
function harvestHeading(){const s=ritu(),n=daysToHarvest(),h=harvest();return {kicker:`HARVEST NO. ${isoWeek()} · ${s.name.toUpperCase()}`,title:'In season this week.',desc:h.length?`${h.length} recipes chosen for ${s.en}. The next harvest opens ${n===1?'tomorrow':`in ${n} days`}.`:'Nothing in season fits your time and nut preferences. Loosen them to see this week’s harvest.'};}
function recipeSection(full=false){const h=harvestHeading(),grid=`<div class="recipe-grid harvest-grid">${harvest().map(cardHTML).join('')}</div>`;if(!full)return `<section class="recipe-section"><span class="section-kicker">02 / ${h.kicker}</span><div class="section-heading"><div><h2>${h.title}</h2><p>${h.desc}</p></div><button class="text-button" data-view="recipes">The full collection ${icon('arrow')}</button></div>${grid}</section>`;return `<section class="recipe-section harvest-section" style="margin-top:0"><span class="section-kicker">01 / ${h.kicker}</span><div class="section-heading"><div><h2>${h.title}</h2><p>${h.desc}</p></div></div>${grid}</section><section class="recipe-section"><span class="section-kicker">02 / THE COLLECTION</span><div class="section-heading"><div><h2>Every recipe, every season.</h2><p>Filter by what you have time for tonight.</p></div></div><div class="filter-toolbar"><div class="chips">${FILTERS.map(t=>`<button class="chip ${filter===t?'active':''}" data-filter="${t}">${t}</button>`).join('')}</div><label class="search-wrap"><span class="sr-only">Search recipes</span>${icon('search')}<input id="recipe-search" placeholder="Search a recipe or ingredient" value="${esc(query)}"></label></div><div class="recipe-grid" id="recipe-grid">${recipeCards()}</div></section>`;}
function soakItems(){return state.plan.map((id,i)=>({r:find(id),i})).filter(x=>x.r&&x.r.soak&&!state.planDone.includes(x.r.id));}
function soakAmount(r){return r.soak.key?quantity(r.soak.key,r.ingredients[r.soak.key]*state.servings/2):`${Math.round(r.soak.grams*state.servings/2)} g`;}
function soakStrip(){const items=soakItems();if(!items.length)return '';return `<section class="soak-strip" aria-labelledby="soak-title"><div class="soak-head"><span class="section-kicker">THE NIGHT BEFORE</span><h3 id="soak-title">Tonight’s soak</h3><p>Satvic cooking starts the evening before. Soak tonight, cook tomorrow.</p></div><ul>${items.map(({r,i})=>{const done=state.soaked.includes(r.id);return `<li class="${done?'done':''}"><label><input type="checkbox" data-soak="${r.id}" ${done?'checked':''}><span><strong>Soak ${soakAmount(r)} ${r.soak.what}</strong><small>${r.soak.hours} hours${r.soak.note?', '+r.soak.note:''} · Day 0${i+1}, ${r.name}</small></span></label></li>`;}).join('')}</ul></section>`;}
function renderPlan(){const s=ritu(),n=state.plan.filter(Boolean).length,who=state.name?`${greeting()}, ${esc(state.name)}. `:'';return `<div class="masthead-space" aria-hidden="true"></div><section class="hero"><div class="hero-art"><img src="assets/hero.jpg" alt="A colourful bowl of fresh vegetables and greens"></div><div class="hero-copy"><span class="eyebrow">${icon('leaf')} ${s.name.toUpperCase()} · ${s.en.toUpperCase()} · WEEK ${isoWeek()}</span><h1>Three meals. One list.<br><em>Done by sunset.</em></h1><p>${who}${s.line}</p><div class="hero-actions"><button class="button primary" data-action="start-cooking">Start cooking ${icon('arrow')}</button><a class="hero-secondary" href="#meal-plan">See this week ${icon('arrow')}</a></div></div><div class="hero-footer"><span>NO ONION · NO GARLIC · COOKED FRESH</span><span>YOUR WEEK ${icon('arrow')}</span></div></section>${steps()}<section id="meal-plan"><span class="section-kicker">01 / THIS WEEK</span><div class="section-heading"><div><h2>Your three meals</h2><p>Chosen for ${s.name}. Swap anything.</p></div><button class="text-button" data-action="fresh-plan">${icon('refresh')} New plan</button></div><div class="day-grid">${state.plan.map((id,i)=>{const r=find(id);return `<article class="day-card"><div class="day-top"><span>DAY 0${i+1}</span><span>${r?(state.planDone.includes(id)?'COOKED ✓':MOMENT[r.moment].short):''}</span></div>${r?`<div class="day-meal"><img src="assets/${r.image}.jpg" alt="" loading="lazy"><div><h3>${r.name}</h3>${meta(r)}</div></div><div class="day-actions"><button class="text-button" data-swap="${i}" aria-label="Swap day ${i+1} meal">${icon('refresh')} Swap</button><button class="cook-button" data-recipe="${id}">${state.planDone.includes(id)?'Cook again':'Cook this'}</button></div>`:`<button class="planned-empty" data-swap="${i}">+ Choose a meal</button>`}</article>`;}).join('')}</div>${soakStrip()}<div class="plan-bottom"><p>${icon('bag')} ${Object.keys(aggregate()).length} ingredients across ${n} ${n===1?'meal':'meals'}. Check the pantry first.</p><button class="button primary small" data-view="shopping">Build my list ${icon('arrow')}</button></div></section>${recipeSection()}`;}
function renderShopping(){const items=aggregate(),keys=Object.keys(items),pantry=keys.filter(k=>state.pantry.includes(k)),need=keys.filter(k=>!state.pantry.includes(k)),bought=need.filter(k=>state.bought.includes(k));const shown=shoppingTab==='pantry'?pantry:need;return `${pageHeading('THE LIST','Buy only what you’ll cook.',`Everything for ${state.plan.filter(Boolean).length} meals, scaled for ${state.servings} ${state.servings===1?'person':'people'}. Mark what’s already at home, then shop the rest.`)}${steps()}<div class="summary-cards"><div class="summary-card"><span>${icon('bag')}</span><div><strong>${need.length-bought.length}</strong><small>items left to buy</small></div></div><div class="summary-card"><span>${icon('check')}</span><div><strong>${pantry.length}</strong><small>already in your pantry</small></div></div><div class="summary-card"><span>${icon('leaf')}</span><div><strong>${state.plan.filter(Boolean).length}</strong><small>meals planned</small></div></div></div><div class="shopping-layout"><div><div class="shopping-panel"><div class="shopping-tabs"><button class="shopping-tab ${shoppingTab==='need'?'active':''}" data-shop-tab="need">To buy · ${need.length}</button><button class="shopping-tab ${shoppingTab==='pantry'?'active':''}" data-shop-tab="pantry">In my pantry · ${pantry.length}</button></div>${shown.length?['FRESH PRODUCE','PANTRY STAPLES'].map(cat=>{const group=shown.filter(k=>ingredients[k].category===cat);return group.length?`<section class="shopping-group"><h3>${cat}</h3>${group.map(key=>`<div class="grocery-row ${state.bought.includes(key)&&shoppingTab==='need'?'bought':''}"><label>${shoppingTab==='need'?`<input type="checkbox" data-bought="${key}" ${state.bought.includes(key)?'checked':''} aria-label="Bought ${ingredients[key].name}">`:icon('check')}<span>${ingredients[key].name}</span></label><small>${quantity(key,items[key])}${buyNote(key,items[key])?` <em>· ${buyNote(key,items[key])}</em>`:''}</small><button data-pantry="${key}">${shoppingTab==='need'?'Have it':'Need it'}</button></div>`).join('')}</section>`:'';}).join(''):`<div class="empty-state">${icon('bag')}<h3>${shoppingTab==='need'?'Nothing left to buy.':'Nothing marked yet.'}</h3><p>${shoppingTab==='need'?'Everything is in your pantry, or your meal plan is empty.':'Tap “Have it” beside an ingredient to move it here.'}</p></div>`}<div style="height:16px"></div></div><div class="list-actions"><button class="button outline" data-action="copy-list">${icon('copy')} Copy shopping list</button><button class="button outline" data-action="print-list">Print list</button></div><p class="form-help">Quantities are combined across your selected recipes. Pantry basics such as water and seasoning are not included.</p></div><aside class="shopping-note">${icon('sprout')}<h3>Less waste,<br>by design.</h3><p>Shared ingredients are combined across your meals, and whole produce is rounded up to what you’d actually pick up at the shop.</p><button class="button primary" data-action="start-cooking">Ready to cook ${icon('arrow')}</button><p class="form-help">Your pantry selections stay saved for your next visit.</p></aside></div>`;}
function renderProgress(){const planned=state.plan.filter(Boolean),done=planned.filter(id=>state.planDone.includes(id)),next=planned.find(id=>!state.planDone.includes(id)),all=done.length===planned.length&&planned.length,earlier=state.cooked.filter(id=>!state.plan.includes(id)&&find(id));return `${pageHeading('YOUR KITCHEN','What you’ve cooked.','No streaks, no scores. Just the meals you actually made.')}<div class="summary-cards"><div class="summary-card"><span>${icon('heart')}</span><div><strong>${state.cooked.length}</strong><small>recipes cooked</small></div></div><div class="summary-card"><span>${icon('check')}</span><div><strong>${done.length} / ${planned.length}</strong><small>of this week’s meals</small></div></div><div class="summary-card"><span>${icon('bag')}</span><div><strong>${Object.keys(aggregate()).filter(k=>state.pantry.includes(k)).length}</strong><small>ingredients from home</small></div></div></div><div class="progress-banner"><h2>${all?'All three, cooked.':planned.length?`${done.length} of ${planned.length} this week.`:'No meals planned yet.'}</h2><p>${all?'That’s the whole week. Start a new plan whenever you’re ready.':next?`Up next: ${find(next).name}.`:'Choose a meal to begin.'}</p><div class="progress-track"><div style="width:${planned.length?done.length/planned.length*100:0}%"></div></div></div><div class="section-heading"><h2>This week</h2><button class="text-button" data-view="plan">Back to my plan ${icon('arrow')}</button></div><div class="week-list">${state.plan.map((id,i)=>{const r=find(id);if(!r)return `<article class="win-card is-waiting"><span class="win-empty" aria-hidden="true">+</span><div><small>DAY 0${i+1}</small><h3>No meal yet</h3></div><button class="cook-button" data-swap="${i}">Choose</button></article>`;const c=state.planDone.includes(id),isNext=id===next;return `<article class="win-card ${c?'is-done':isNext?'is-next':'is-waiting'}"><img src="assets/${r.image}.jpg" alt="" loading="lazy"><div><small>DAY 0${i+1} · ${MOMENT[r.moment].short}</small><h3>${r.name}</h3><p>${c?esc(state.feedback[id]||'Cooked.'):isNext?'Up next.':'Waiting its turn.'}</p></div>${c?`<span>${icon('check')} Cooked</span>`:`<button class="cook-button" data-recipe="${id}">${isNext?'Cook now':'View'}</button>`}</article>`;}).join('')}</div>${earlier.length?`<div class="section-heading" style="margin-top:34px"><h2>Cooked before</h2></div>${earlier.map(id=>{const r=find(id);return `<article class="win-card is-done"><img src="assets/${r.image}.jpg" alt="" loading="lazy"><div><h3>${r.name}</h3><p>${esc(state.feedback[id]||'Cooked.')}</p></div><span>${icon('check')} Cooked</span></article>`;}).join('')}`:''}`;}
function render(){document.body.dataset.view=view;queueMicrotask(()=>document.dispatchEvent(new CustomEvent('kitchen:render',{detail:{view}})));document.getElementById('content').innerHTML=view==='plan'?renderPlan():view==='recipes'?pageHeading('THE RECIPES','Cooked fresh. Eaten early.',`${recipes.length} satvic recipes. No onion, no garlic, nothing reheated. The ones that need soaking tell you the night before.`)+recipeSection(true):view==='shopping'?renderShopping():renderProgress();document.querySelectorAll('.nav-item').forEach(el=>{const active=el.dataset.view===view;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});document.getElementById('preferences-summary').textContent=`${state.servings} ${state.servings===1?'person':'people'} · ${state.time} min`;document.getElementById('nav-list-count').textContent=Object.keys(aggregate()).filter(k=>!state.pantry.includes(k)&&!state.bought.includes(k)).length;hydrateIcons();save();}
function go(next,fromHistory=false){const wasOpen=document.querySelector('.sidebar').classList.contains('open');view=next;setMenu(false);render();if(!fromHistory){const entry={view:next};if(history.state&&history.state.dialog)history.replaceState(entry,'','#'+next);else if(!history.state||history.state.view!==next)history.pushState(entry,'','#'+next);}window.scrollTo({top:0,behavior:'smooth'});if(wasOpen)document.getElementById('content').focus({preventScroll:true});}
function showPreferences(){document.getElementById('servings').value=state.servings;document.getElementById('cooking-time').value=state.time;document.getElementById('nut-free').checked=state.nutFree;openDialog(document.getElementById('preferences-dialog'));}
function openRecipe(id){const r=find(id);if(!r)return;const dialog=document.getElementById('recipe-dialog');dialog.setAttribute('aria-label',r.name);const soaked=state.soaked.includes(id);dialog.innerHTML=`<button class="dialog-close" data-close="recipe-dialog" aria-label="Close recipe">×</button><div class="recipe-detail"><div class="recipe-detail-art"><img src="assets/${r.image}.jpg" alt="${r.name}, illustrative photograph"><span class="image-tag">${inSeason(r)?`In season · ${ritu().name}`:r.category}</span></div><div class="recipe-detail-content"><span class="eyebrow">${MOMENT[r.moment].label.toUpperCase()}</span><h2>${r.name}</h2><p>${r.desc}</p><div class="detail-tags"><span>${icon('clock')} ${r.time} min active</span><span>${icon('people')} Serves ${state.servings}</span><span>${r.raw?'Raw':'Cooked fresh'}</span><span>No onion · no garlic</span></div><div class="why-note"><strong>Why it’s satvic</strong><p>${r.why}</p></div><h3>Ingredients</h3><ul class="ingredient-mini">${scaledIngredients(r).map(i=>`<li>${i.name} · ${i.amount}</li>`).join('')}</ul><div class="prep-note"><strong>Before you start:</strong> ${r.prep}${r.soak?`<label class="soak-check"><input type="checkbox" data-soak="${id}" ${soaked?'checked':''}> <span>${soaked?'Soaked':`Mark the ${r.soak.what} as soaked`}</span></label>`:''}</div><h3>Method</h3>${r.steps.map((step,i)=>`<label class="cook-step"><input type="checkbox" aria-label="Step ${i+1} complete"><span>${scaledStep(step)}</span></label>`).join('')}<div class="detail-bottom"><button class="button primary" data-cook-mode="${id}">${icon('sun')} Start cooking mode</button><button class="button outline" data-cooked="${id}">${icon('check')} I cooked this</button>${state.plan.includes(id)?'':`<button class="button outline" data-add="${id}">Add to my plan</button>`}</div><p class="form-help" style="margin-top:15px">Illustrative recipe and photography for this independent concept. Check ingredients against your household’s dietary needs.</p></div></div>`;openDialog(dialog);document.dispatchEvent(new CustomEvent('kitchen:recipe-open',{detail:{id}}));}
function showSwap(index,selectedId){swapIndex=index;const dialog=document.getElementById('swap-dialog');dialog.innerHTML=`<button class="dialog-close" data-close="swap-dialog" aria-label="Close meal choices">×</button><span class="eyebrow">SWAP</span><h2>${selectedId?'Pick a day.':'Choose another meal.'}</h2><p class="muted">${selectedId?'Choose where this meal fits in your plan.':`Choose a meal for day ${index+1}, matched to your preferences.`}</p>${selectedId?state.plan.map((id,i)=>`<button class="swap-row" data-assign="${selectedId}" data-slot="${i}"><span><strong>Day 0${i+1}</strong><small>${find(id)?.name||'Choose a meal'}</small></span><span>+</span></button>`).join(''):[...available().filter(inSeason),...available().filter(r=>!inSeason(r))].map(r=>`<button class="swap-row" data-assign="${r.id}" data-slot="${index}"><img src="assets/${r.image}.jpg" alt=""><span><strong>${r.name}</strong><small>${r.time} min · ${r.raw?'Raw':'Cooked fresh'}${inSeason(r)?' · In season':''}</small></span><span>${state.plan[index]===r.id?'✓':'+'}</span></button>`).join('')}<p class="form-help" style="margin-top:20px">${selectedId?'Shopping quantities will update automatically.':'You can adjust time and ingredient preferences from the top bar.'}</p>`;openDialog(dialog);}
function addRecipe(id){const empty=state.plan.indexOf(null);if(empty>=0){state.plan[empty]=id;render();document.dispatchEvent(new CustomEvent('kitchen:plan-change'));toast('Added to your plan.');}else{document.getElementById('recipe-dialog').close();showSwap(0,id);}}
function markCooked(id){if(!state.cooked.includes(id))state.cooked.push(id);if(state.plan.includes(id)&&!state.planDone.includes(id))state.planDone.push(id);document.dispatchEvent(new CustomEvent('kitchen:cooked',{detail:{id}}));save();render();const dialog=document.getElementById('recipe-dialog');dialog.innerHTML=`<div style="padding:45px 35px;text-align:center;max-width:520px;margin:auto"><button class="dialog-close" data-close="recipe-dialog" aria-label="Close feedback">×</button><div style="color:#8caa6d">${icon('sprout')}</div><span class="eyebrow" style="margin:15px 0">COOKED</span><h2 style="font-size:32px;line-height:1.3;letter-spacing:-1px">Made by you.<br>Fresh, today.</h2><p class="muted">How did the ${esc(find(id).name.toLowerCase())} go?</p><div class="feedback-options" style="justify-content:center">${['Easy & enjoyable','Took longer','Missing ingredients'].map(f=>`<button data-feedback="${id}" data-value="${f}">${f}</button>`).join('')}</div><button class="button primary" data-action="see-wins">See what I’ve cooked ${icon('arrow')}</button><p class="form-help" style="margin-top:15px">Your feedback is saved on this device.</p></div>`;if(!dialog.open)openDialog(dialog);dialog.setAttribute('aria-label','Cooking feedback');dialog.querySelector('[data-feedback]')?.focus();}
document.addEventListener('click',event=>{const el=event.target.closest('button,a[data-view]');if(!el)return;const d=el.dataset;if(d.view){go(d.view);return;}if(d.close){document.getElementById(d.close).close();return;}if(d.filter){filter=d.filter;render();return;}if(d.recipe){openRecipe(d.recipe);return;}if(d.add){addRecipe(d.add);return;}if(d.swap!==undefined){showSwap(Number(d.swap));return;}if(d.assign){const target=Number(d.slot),existing=state.plan.indexOf(d.assign),displaced=state.plan[target];if(existing>=0&&existing!==target)state.plan[existing]=displaced;state.plan[target]=d.assign;state.planDone=state.planDone.filter(id=>state.plan.includes(id));document.getElementById('swap-dialog').close();render();toast('Swapped. Your list is updated.');document.dispatchEvent(new CustomEvent('kitchen:plan-change'));return;}if(d.pantry){state.pantry=state.pantry.includes(d.pantry)?state.pantry.filter(k=>k!==d.pantry):[...state.pantry,d.pantry];render();return;}if(d.shopTab){shoppingTab=d.shopTab;render();return;}if(d.cooked){markCooked(d.cooked);return;}if(d.cookMode){window.CookMode?.open(d.cookMode);return;}if(d.feedback){state.feedback[d.feedback]=d.value;save();document.getElementById('recipe-dialog').close();go('progress');toast('Noted. Thank you.');return;}if(d.action==='start-cooking'){const id=state.plan.find(id=>id&&!state.planDone.includes(id))||state.plan.find(Boolean);id?openRecipe(id):(go('recipes'),toast('Choose a meal to get started.'));}if(d.action==='fresh-plan'){const choices=[...available().filter(inSeason),...available().filter(r=>!inSeason(r))];if(!choices.length){toast('Try adjusting your preferences.');return;}const offset=choices.findIndex(r=>r.id===state.plan[0]);state.plan=Array.from({length:3},(_,i)=>i<choices.length?choices[(offset+i+1)%choices.length].id:null);state.planDone=[];state.bought=[];render();toast(`New plan, chosen for ${ritu().name}.`);document.dispatchEvent(new CustomEvent('kitchen:plan-change'));}if(d.action==='clear-filter'){query='';filter='All recipes';render();}if(d.action==='copy-list'){const items=aggregate();const text=`My Satvic Kitchen shopping list\n${state.servings} people · ${state.plan.filter(Boolean).length} meals\n\n`+Object.keys(items).filter(k=>!state.pantry.includes(k)).map(k=>`${state.bought.includes(k)?'✓':'□'} ${ingredients[k].name} — ${quantity(k,items[k])}`).join('\n');if(navigator.clipboard){navigator.clipboard.writeText(text).then(()=>toast('List copied.')).catch(()=>toast('Copy unavailable. You can print your list instead.'));}else toast('Copy unavailable. You can print your list instead.');}if(d.action==='print-list')window.print();if(d.action==='see-wins'){document.getElementById('recipe-dialog').close();go('progress');}});
document.addEventListener('change',event=>{const key=event.target.dataset.bought;if(key){state.bought=event.target.checked?[...new Set([...state.bought,key])]:state.bought.filter(k=>k!==key);render();}});
document.addEventListener('change',event=>{const id=event.target.dataset.soak;if(!id)return;state.soaked=event.target.checked?[...new Set([...state.soaked,id])]:state.soaked.filter(k=>k!==id);const label=event.target.closest('.soak-check')?.querySelector('span');if(label)label.textContent=event.target.checked?'Soaked':`Mark the ${find(id).soak.what} as soaked`;render();if(event.target.checked)toast('Soaked. Tomorrow’s meal is ready to go.');});
document.addEventListener('input',event=>{if(event.target.id==='recipe-search'){query=event.target.value;document.getElementById('recipe-grid').innerHTML=recipeCards();}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();go('plan');});
document.getElementById('open-preferences').addEventListener('click',showPreferences);
document.getElementById('preferences-form').addEventListener('submit',e=>{e.preventDefault();state.servings=Math.max(1,Math.min(8,Number(document.getElementById('servings').value)||2));state.time=Number(document.getElementById('cooking-time').value);state.nutFree=document.getElementById('nut-free').checked;document.getElementById('preferences-dialog').close();render();toast('Saved. Suggestions now fit your kitchen.');});
for(const [id,delta]of [['servings-down',-1],['servings-up',1]])document.getElementById(id).addEventListener('click',()=>{const el=document.getElementById('servings');el.value=Math.max(1,Math.min(8,(Number(el.value)||2)+delta));});
function setMenu(open){document.querySelector('.sidebar').classList.toggle('open',open);document.getElementById('mobile-menu').setAttribute('aria-expanded',String(open));}
document.getElementById('mobile-menu').addEventListener('click',()=>setMenu(!document.querySelector('.sidebar').classList.contains('open')));
document.addEventListener('pointerdown',e=>{if(document.querySelector('.sidebar.open')&&!e.target.closest('.sidebar'))setMenu(false);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.sidebar.open')){setMenu(false);document.getElementById('mobile-menu').focus();}});
document.getElementById('reset-demo').addEventListener('click',()=>{state=fresh();view='plan';filter='All recipes';query='';shoppingTab='need';render();toast('Started over.');window.Ritual?.open();});
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}}));
// Back button / gesture: each view has its own history entry, and an open dialog adds one more,
// so Back closes the dialog first, then steps through views, instead of leaving the app.
function openDialog(dialog){dialog.showModal();const entry={view,dialog:dialog.id};if(history.state&&history.state.dialog)history.replaceState(entry,'');else history.pushState(entry,'');}
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('close',()=>setTimeout(()=>{if(!document.querySelector('dialog[open]')&&history.state&&history.state.dialog)history.back();},0)));
addEventListener('popstate',e=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());const next=(e.state&&e.state.view)||location.hash.slice(1);if(VIEWS.includes(next)&&next!==view)go(next,true);});
history.replaceState({view},'','#'+view);
render();
// Offline support and install-to-home-screen. Browsers only allow service workers on https or localhost.
if('serviceWorker' in navigator&&(location.protocol==='https:'||['localhost','127.0.0.1'].includes(location.hostname)))addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));
